 * Turns source text into the token stream the language's grammar is built
 * from: idents, keywords, numbers, puncts, strings and rawstrings. Throws a
 * LexError, positioned per the spec, at the first construct that does not
 * scan.
 */

import { Scanner, LexError } from './scanner.js'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const isIdentStart = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isIdentPart = (c) => c !== undefined && /^[A-Za-z0-9_]$/.test(c)
const isDec = (c) => c !== undefined && /^[0-9]$/.test(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c !== undefined && /^[01]$/.test(c)
const isOct = (c) => c !== undefined && /^[0-7]$/.test(c)

export function scan(input) {
  const s = new Scanner(input)
  const tokens = []
  while (true) {
    skipTrivia(s)
    if (s.eof()) break
    tokens.push(scanToken(s))
  }
  return tokens
}

function skipTrivia(s) {
  while (!s.eof()) {
    const c = s.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '/') {
      while (!s.eof() && s.peek() !== '\n') s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '*') {
      skipBlockComment(s)
      continue
    }
    break
  }
