  const openPos = s.pos()
  s.advance()
  s.advance()
  let depth = 1
  while (depth > 0) {
    if (s.eof()) throw new LexError(openPos, 'unterminated block comment')
    if (s.peek() === '/' && s.peek(1) === '*') {
      s.advance()
      s.advance()
      depth++
      continue
    }
    if (s.peek() === '*' && s.peek(1) === '/') {
      s.advance()
      s.advance()
      depth--
      continue
    }
    s.advance()
  }
}

