  const startPos = s.pos()
  const c = s.peek()
  if (c === '"') return scanString(s, startPos)
  if (c === 'r' && s.peek(1) === '"') return scanRawString(s, startPos)
  if (isIdentStart(c)) return scanIdent(s, startPos)
  if (isDec(c)) return scanNumber(s, startPos)
