    const c = s.peek()
    if (isDigitFn(c)) {
      text += s.advance()
      any = true
      continue
    }
    if (c === '_' && any && isDigitFn(s.peek(1))) {
      text += s.advance()
      continue
    }
    break
  }
  return { text, any }
