      text += s.advance()
      const { text: fracDigs } = scanDigitsRun(s, isDec)
      text += fracDigs
    }
    if (s.peek() === 'e' || s.peek() === 'E') {
      const n1 = s.peek(1)
      if (isDec(n1)) {
        text += s.advance()
        const { text: expDigs } = scanDigitsRun(s, isDec)
        text += expDigs
      } else if ((n1 === '+' || n1 === '-') && isDec(s.peek(2))) {
        text += s.advance() + s.advance()
        const { text: expDigs } = scanDigitsRun(s, isDec)
        text += expDigs
