  while (!s.eof() && isIdentPart(s.peek())) trailing += s.advance()
  text += trailing
  if (prefixEmpty || trailing) throw new LexError(startPos, `invalid number ${text}`)
  return { kind: 'number', line: startPos.line, col: startPos.col, text }
}

function scanString(s, startPos) {
  s.advance() // opening quote
  let value = ''
  const guard = () => {
    if (s.eof()) throw new LexError(startPos, 'unterminated string')
    if (s.peek() === '\n') throw new LexError(s.pos(), 'newline in string')
  }
  while (true) {
    guard()
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\\') {
      const bsPos = s.pos()
      s.advance()
      guard()
      const e = s.peek()
      if (e === 'n') {
        value += '\n'
        s.advance()
      } else if (e === 't') {
        value += '\t'
        s.advance()
      } else if (e === 'r') {
        value += '\r'
        s.advance()
      } else if (e === '\\') {
        value += '\\'
        s.advance()
      } else if (e === '"') {
        value += '"'
        s.advance()
      } else if (e === '0') {
        value += '\0'
        s.advance()
      } else if (e === 'x') {
        s.advance()
        guard()
        const h1 = s.peek()
        if (!isHex(h1)) throw new LexError(bsPos, 'invalid escape \\x')
        s.advance()
        guard()
        const h2 = s.peek()
        if (!isHex(h2)) throw new LexError(bsPos, 'invalid escape \\x')
        s.advance()
        value += String.fromCharCode(parseInt(h1 + h2, 16))
      } else if (e === 'u') {
        s.advance()
        guard()
        if (s.peek() !== '{') throw new LexError(bsPos, 'invalid escape \\u')
        s.advance()
        let hex = ''
        while (true) {
          guard()
          const hc = s.peek()
          if (!isHex(hc)) break
          hex += s.advance()
        }
        if (hex.length === 0) throw new LexError(bsPos, 'invalid escape \\u')
        guard()
        if (s.peek() !== '}') throw new LexError(bsPos, 'invalid escape \\u')
        const cp = parseInt(hex, 16)
        if (cp > 0x10ffff) throw new LexError(bsPos, 'invalid escape \\u')
        s.advance()
        value += String.fromCodePoint(cp)
      } else {
        throw new LexError(bsPos, `invalid escape \\${e}`)
      }
      continue
    }
    value += s.advance()
  }
  return { kind: 'string', line: startPos.line, col: startPos.col, value }
}

function scanRawString(s, startPos) {
  s.advance() // 'r'
  s.advance() // opening quote
  let value = ''
  while (true) {
    if (s.eof()) throw new LexError(startPos, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    value += s.advance()
  }
  return { kind: 'rawstring', line: startPos.line, col: startPos.col, value }
}
"}

